"use client"

import { AnimatePresence, motion } from "motion/react"
import { type ReactNode, useState } from "react"
import { cn } from "@/lib/utils"

export type FanCardItem = {
  id: string
  title: string
  subtitle: string
  bg: string
  textColor: string
  subtitleColor: string
  defaultRotation: number
  stackIndex: number
  content?: ReactNode
}

export const DEFAULT_FAN_CARDS: FanCardItem[] = [
  {
    id: "working",
    title: "Working Knowledge",
    subtitle:
      "Foundational concepts and practical frameworks for understanding complex systems and workflows.",
    bg: "#F26419",
    textColor: "#fff",
    subtitleColor: "rgba(255,255,255,0.78)",
    defaultRotation: -14,
    stackIndex: 0,
  },
  {
    id: "practical",
    title: "Practical Demonstration",
    subtitle:
      "Step-by-step walkthroughs that bridge theory and real-world application seamlessly.",
    bg: "#ECEAE3",
    textColor: "#1a1a1a",
    subtitleColor: "rgba(0,0,0,0.58)",
    defaultRotation: -6,
    stackIndex: 1,
  },
  {
    id: "collaborate",
    title: "Collaborate with AI",
    subtitle:
      "Leverage artificial intelligence as a creative partner to enhance productivity and innovation.",
    bg: "#3B82F6",
    textColor: "#fff",
    subtitleColor: "rgba(255,255,255,0.78)",
    defaultRotation: 1,
    stackIndex: 2,
  },
  {
    id: "means",
    title: "Means & Methods",
    subtitle:
      "Proven strategies and methodologies that streamline workflows and optimize outcomes.",
    bg: "#22C55E",
    textColor: "#0f3a1a",
    subtitleColor: "rgba(0,0,0,0.58)",
    defaultRotation: 9,
    stackIndex: 3,
  },
  {
    id: "interface",
    title: "Interface Kit",
    subtitle:
      "A comprehensive collection of UI components and patterns for building beautiful interfaces.",
    bg: "#1C1C1E",
    textColor: "#fff",
    subtitleColor: "rgba(255,255,255,0.65)",
    defaultRotation: 16,
    stackIndex: 4,
  },
]

export type FanCardsProps = {
  cards?: FanCardItem[]
  spread?: number
  rotateStep?: number
  springStiffness?: number
  springDamping?: number
  className?: string
}

const CARD_W = 260
const CARD_H = 340
const BASE_SPREAD = 95
const BASE_ROTATION_STEP = 8
const FAN_X = [-195, -100, -5, 90, 185]
const FAN_Y = [45, 22, 4, 18, 36]

const SPRING_ENTRY = {
  type: "spring" as const,
  stiffness: 300,
  damping: 20,
  mass: 1,
}

const SPRING_RECESS = {
  type: "spring" as const,
  stiffness: 280,
  damping: 28,
  mass: 1,
}

const SPRING_RETURN = {
  type: "spring" as const,
  stiffness: 260,
  damping: 26,
  mass: 1,
}

type FanCardProps = {
  card: FanCardItem
  fanX: number
  fanY: number
  rotation: number
  isSelected: boolean
  isCollapsed: boolean
  zIndex: number
  springEntry: typeof SPRING_ENTRY
  springRecess: typeof SPRING_RECESS
  springReturn: typeof SPRING_RETURN
  onClick: () => void
}

const FanCard = ({
  card,
  fanX,
  fanY,
  rotation,
  isSelected,
  isCollapsed,
  zIndex,
  springEntry,
  springRecess,
  springReturn,
  onClick,
}: FanCardProps) => {
  const [hovered, setHovered] = useState(false)

  const target = isSelected
    ? { x: 0, y: -48, rotate: 0, scale: 1.12 }
    : isCollapsed
      ? {
          x: fanX * 0.38,
          y: fanY + 122,
          rotate: rotation * 0.55,
          scale: hovered ? 0.8 : 0.76,
        }
      : {
          x: fanX,
          y: fanY,
          rotate: rotation,
          scale: hovered ? 1.05 : 1,
        }

  const transition = isSelected
    ? springEntry
    : isCollapsed
      ? springRecess
      : springReturn

  return (
    <motion.div
      style={{
        position: "absolute",
        width: CARD_W,
        height: CARD_H,
        top: 0,
        left: "50%",
        marginLeft: -CARD_W / 2,
        zIndex,
        cursor: isSelected ? "zoom-out" : "pointer",
        borderRadius: 20,
        overflow: "hidden",
        transformOrigin: "bottom center",
      }}
      initial={false}
      animate={target}
      transition={transition}
      onClick={(event) => {
        event.stopPropagation()
        onClick()
      }}
      onHoverStart={() => setHovered(true)}
      onHoverEnd={() => setHovered(false)}
      whileTap={!isSelected ? { scale: isCollapsed ? 0.72 : 0.96 } : undefined}
      role="button"
      tabIndex={0}
      aria-pressed={isSelected}
      aria-label={card.title}
      onKeyDown={(event) => {
        if (event.key === "Enter" || event.key === " ") {
          event.preventDefault()
          onClick()
        }
      }}
    >
      <motion.div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 20,
          background: card.bg,
          boxShadow: isSelected
            ? "0 36px 90px rgba(0,0,0,0.24), 0 10px 28px rgba(0,0,0,0.14)"
            : hovered
              ? "0 22px 56px rgba(0,0,0,0.2), 0 5px 18px rgba(0,0,0,0.1)"
              : "0 8px 32px rgba(0,0,0,0.14), 0 2px 8px rgba(0,0,0,0.08)",
        }}
      />

      <div className="pointer-events-none relative flex h-full flex-col">
        <div className="min-h-0 flex-1 overflow-hidden">{card.content}</div>

        <div className="shrink-0 px-6 pb-6 pt-2">
          <motion.h2
            animate={{
              fontSize: isSelected ? 22 : 17,
              fontWeight: isSelected ? 800 : 700,
            }}
            transition={{ duration: 0.28, ease: [0.22, 1, 0.36, 1] }}
            style={{
              color: card.textColor,
              lineHeight: 1.15,
              letterSpacing: "-0.025em",
            }}
          >
            {card.title}
          </motion.h2>

          <AnimatePresence mode="wait">
            {isSelected ? (
              <motion.p
                key={`${card.id}-subtitle`}
                initial={{ opacity: 0, y: 14, filter: "blur(6px)" }}
                animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                exit={{
                  opacity: 0,
                  y: 6,
                  filter: "blur(4px)",
                  transition: { duration: 0.16, ease: "easeIn" },
                }}
                transition={{
                  opacity: {
                    delay: 0.2,
                    duration: 0.34,
                    ease: [0.22, 1, 0.36, 1],
                  },
                  y: {
                    delay: 0.2,
                    duration: 0.4,
                    ease: [0.22, 1, 0.36, 1],
                  },
                  filter: { delay: 0.2, duration: 0.3 },
                }}
                style={{
                  marginTop: 10,
                  fontSize: 14,
                  lineHeight: 1.6,
                  color: card.subtitleColor,
                  fontWeight: 400,
                  maxWidth: 220,
                }}
              >
                {card.subtitle}
              </motion.p>
            ) : null}
          </AnimatePresence>
        </div>
      </div>

      <motion.div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: 20,
          background:
            "linear-gradient(135deg, rgba(255,255,255,0.14) 0%, transparent 55%)",
          pointerEvents: "none",
        }}
        animate={{ opacity: hovered && !isSelected ? 1 : 0 }}
        transition={{ duration: 0.18 }}
      />
    </motion.div>
  )
}

export function FanCards({
  cards = DEFAULT_FAN_CARDS,
  spread = BASE_SPREAD,
  rotateStep = BASE_ROTATION_STEP,
  springStiffness = SPRING_RETURN.stiffness,
  springDamping = SPRING_RETURN.damping,
  className,
}: FanCardsProps) {
  const [selectedId, setSelectedId] = useState<string | null>(null)
  const spreadScale = spread / BASE_SPREAD
  const rotationScale = rotateStep / BASE_ROTATION_STEP
  const isFocusMode = selectedId !== null

  const springReturn = {
    ...SPRING_RETURN,
    stiffness: springStiffness,
    damping: springDamping,
  }
  const springEntry = {
    ...SPRING_ENTRY,
    stiffness: Math.max(200, springStiffness + 40),
    damping: Math.max(16, springDamping - 6),
  }
  const springRecess = {
    ...SPRING_RECESS,
    stiffness: springStiffness,
    damping: springDamping,
  }

  const handleClose = () => setSelectedId(null)

  const handleCardClick = (id: string) => {
    setSelectedId((current) => (current === id ? null : id))
  }

  return (
    <div
      className={cn(
        "relative flex min-h-[620px] w-full items-center justify-center overflow-hidden select-none",
        className,
      )}
    >
      <AnimatePresence>
        {isFocusMode ? (
          <motion.div
            key="backdrop"
            className="absolute inset-0 z-10"
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: 0 }}
            onClick={handleClose}
          />
        ) : null}
      </AnimatePresence>

      <div
        className="relative z-20"
        style={{
          width: CARD_W + 380,
          height: CARD_H + 120,
        }}
      >
        {cards.map((card) => {
          const isSelected = card.id === selectedId
          const isCollapsed = isFocusMode && !isSelected
          const zIndex = isSelected
            ? 100
            : isFocusMode
              ? card.stackIndex + 30
              : card.stackIndex + 1
          const fanX = FAN_X[card.stackIndex] ?? 0
          const fanY = FAN_Y[card.stackIndex] ?? 0

          return (
            <FanCard
              key={card.id}
              card={card}
              fanX={fanX * spreadScale}
              fanY={fanY}
              rotation={card.defaultRotation * rotationScale}
              isSelected={isSelected}
              isCollapsed={isCollapsed}
              zIndex={zIndex}
              springEntry={springEntry}
              springRecess={springRecess}
              springReturn={springReturn}
              onClick={() => handleCardClick(card.id)}
            />
          )
        })}
      </div>
    </div>
  )
}
